// This file carries the Aruba Central device icons as self-contained
// data URIs, the same pattern internal/render/drawio/logo.go uses for
// the OSIRIS JSON word mark. Since still there is no dedicated draw.io
// HPE Arubacentral library a set of dedicated icons have been designed
// in Inkscape to represent an initial set of devices category improbing
// the topology composition, each icon is a flat, single-path SVG
// pictogram; all four share the same 33.87x33.87 intrinsic viewBox
// (square), so one icon geometry constant covers all of them.
//
// draw.io stores an image style as image=data:<mediatype>,<b64> with
// the base64 payload placed directly after the comma.

package arubacentral

// iconIntrinsic is the geometry, in mxGraph user units, all four
// device icons share.
const iconIntrinsic = 40

// gatewayIconDataURI is the network.gateway device icon.
const gatewayIconDataURI = `data:image/svg+xml,`

// switchIconDataURI is the network.switch device icon for a switch
// that is not VSX-paired with another switch.
const switchIconDataURI = `data:image/svg+xml,`

// accesspointIconDataURI is the osiris.hpe.arubacentral.accesspoint
// device icon.
const accesspointIconDataURI = `data:image/svg+xml,`

// switchStackIconDataURI is the network.switch device icon for a
// switch that participates in an osiris.hpe.arubacentral.vsx
// connection with another switch (see stacked in topology.go).
const switchStackIconDataURI = `data:image/svg+xml,`
